import Synchronization

final class Cache {
    private let state = Mutex<[String: Entry]>([:])

    func find(_ key: String) -> Entry {
        state.withLock { entries in
            findImpl(key, in: &entries)   // lock held: no re-acquisition
        }
    }
    // findImpl assumes the lock is held: lookup, insert on miss, return.
}

actor Cache {
    private var entries: [String: Entry] = [:]

    func find(_ key: String) -> Entry {
        if let e = entries[key] { return e }
        return insertImpl(key)              // isolated: no lock, no re-acquisition
    }

    private func insertImpl(_ key: String) -> Entry {   // assumes isolation
        let e = Entry(key)
        entries[key] = e
        return e
    }
}

